/* Seed images inlined as data URLs.
   Not an optimisation — a necessity. A page opened from file:// cannot read
   pixels back off a canvas that has drawn a local file (the canvas is tainted
   and getImageData throws). Data URLs are same-origin, so analysis works with
   no server and no browser flags. Regenerate with tools/build-seeds.py.
*/
const SEED_DATA = {
  '10dark': 'data:image/jpeg;base64,',
  'blackdashboard': 'data:image/jpeg;base64,',
  'blueredrun': 'data:image/jpeg;base64,',
  'bluescreensplash': 'data:image/jpeg;base64,',
  'brightsquare': 'data:image/jpeg;base64,',
  'goast': 'data:image/jpeg;base64,',
  'goldlake': 'data:image/jpeg;base64,',
  'poster100': 'data:image/jpeg;base64,',
};